// TH14 synthetic bullet aliases used by this card (see transcribe/th14/touhou-bullets.ecl).
// Native type0..23 map to the same-numbered modern slot; type24..42 map to slot+1.
const TH14_SHARD: int = 512;   // native type 10
const TH14_OVAL: int = 672;    // native type 20

// TH14 v1.00b Stage 1 midboss nonspell "MBoss1" — synthetic training card.
//
// Source mapping (transcribe/work/th14/th14_s1_mb1/source.txt):
//   MBoss1          st01mbs.ecl.txt:58-76   entry / movement loop / async burst calls
//   MBoss1_at       st01mbs.ecl.txt:78-134  ring bursts every 6 (E/N/H) or 4 (L) frames
//   MBoss1_at2      st01mbs.ecl.txt:136-220 two mirrored oval fans, STEP turn +/-90 deg
//   MBoss           st01mbs.ecl.txt:8-56    common entry replayed (pos / 100f interpolation / limit)
//   MBossEscape     st01mbs.ecl.txt:447-469 timeout exit context (no next attack)
//
// Approved omissions used here: EffChargePoint3 / fog / ANM / sounds are pure visuals;
// the bullet birth ANIM+SPEEDUP records are birth stage (native ANIM retro-displacement -4*v
// is kept through sh_dist); chapter/drop/scoring bookkeeping is not simulated.

const TIME_LIMIT: int = 1924;        // 120 opening + 1800 window (1440 interrupt + 360 tail) + 4
const OPENING_BUFFER: int = 120;

// Common MBoss entry (st01mbs.ecl.txt:39-42): movePos(-192,-64), movePosTime(100,4,0,128), wait40.
const ENTRY_X: fx = -192fx;
const ENTRY_Y: fx = -64fx;
const HOME_Y: fx = 128fx;

// Per-enemy shared slots (owner = real boss).
const SLOT_MOVE_STEP: int = 0;       // moveRand step counter, 1..60
const SLOT_TIMEOUT: int = 1;         // set once the native 1440-frame interrupt fires
const SLOT_DIR_COS: int = 0;         // moveRand logical unit direction
const SLOT_DIR_SIN: int = 1;

// st01mbs.ecl.txt:102 / :153 second etAngle argument 0.034906585 rad = 2 deg, in BAM.
const LAYER_STEP_2DEG: int = 364;

// at2 source index 1 EX record: STEP a=60 b=1 c=0 d=0 r=+/-pi/2, s=1.0 (Easy) or 1.5.
// Record 0 (ANIM a=1) is the omitted birth stage, so STEP starts at target birth.
xformdef AT2_TURN_R(tail_speed: fx) {
    @60 step_speed(0fx, 60);
    turn(90deg);
    set_speed(tail_speed);
}
xformdef AT2_TURN_L(tail_speed: fx) {
    @60 step_speed(0fx, 60);
    turn(-90deg);
    set_speed(tail_speed);
}

// ---- common MBoss entry replay + timeout watchdog -------------------------

async sub timeout_watch() {
    wait(1439);
    set_self_int(SLOT_TIMEOUT, 1);
}

// ---- MBoss1_at: fixed-direction rings, base rotates +/-10deg per burst ----

async sub burst(base0: angle, step_bam: int, inc: angle) {
    var rank: int = global(GVAR_RANK);
    var ways: int = 8;               // etCount count: E8 N8 H10 L12
    var layers: int = 1;             // etCount layers: E1 N2 H3 L5
    var v0: fx = 1.1fx;              // etSpeed speed0: E1.1 N1.1 H1.4 L2.1
    var shots: int = 6;              // diffI($F,6,8,8,12)
    var gap: int = 6;                // wait after etOn: 6, Lunatic 4
    if rank == RANK_NORMAL { layers = 2; shots = 8; }
    if rank == RANK_HARD { ways = 10; layers = 3; v0 = 1.4fx; shots = 8; }
    if rank == RANK_LUNATIC { ways = 12; layers = 5; v0 = 2.1fx; shots = 12; gap = 4; }
    var vstep: fx = 0fx;             // etSpeed speed1 = 1.0f for every rank
    if layers > 1 { vstep = (1fx - v0) / ((layers - 1) as fx); }

    sh_reset(0);
    sh_sprite(0, TH14_SHARD, 6);     // etSprite(0,10,6)
    sh_ring(0, 1);                   // etAim(0,3): fixed-direction full ring
    sh_aim(0, 0);
    sh_count(0, ways, 1);            // one speed layer per sh_fire: sh_dist differs per layer

    var base: angle = base0;
    var j: int = 0;
    while j < shots {
        if self_int(SLOT_TIMEOUT) != 0 { return; }
        var q: int = 0;
        while q < layers {
            var v: fx = v0 + vstep * (q as fx);
            sh_speed(0, v, 0fx);
            sh_angle(0, base + ((q * step_bam) as angle), 0deg);
            sh_dist(0, 0fx - (4fx * v));   // ANIM entry position -= 4*velocity
            sh_fire(0);
            q = q + 1;
        }
        base = base + inc;
        wait(gap);
        j = j + 1;
    }
}

// ---- MBoss1_at2: 1 way x 6 layers oval fan ------------------------------

sub emit_fan(slot: int, base_bam: int, step_bam: int, v0: fx, vstep: fx) {
    var q: int = 0;
    while q < 6 {
        var v: fx = v0 + vstep * (q as fx);
        sh_speed(slot, v, 0fx);
        sh_angle(slot, (base_bam + q * step_bam) as angle, 0deg);
        sh_dist(slot, 0fx - (4fx * v));    // ANIM entry position -= 4*velocity
        sh_fire(slot);
        q = q + 1;
    }
}

async sub at2() {
    var rank: int = global(GVAR_RANK);
    var v0: fx = 9fx;                // etSpeed speed0: E9.0 else 8.0
    if rank >= RANK_NORMAL { v0 = 8fx; }
    var tail: fx = 1fx;              // STEP target speed: E1.0 else 1.5
    if rank >= RANK_NORMAL { tail = 1.5fx; }
    var first_wait: int = 300;       // wait before the first burst: 300, Lunatic 150
    if rank == RANK_LUNATIC { first_wait = 150; }
    var gap: int = 160;              // wait after emitter 2: 160, Lunatic 80
    if rank == RANK_LUNATIC { gap = 80; }
    var groups: int = 1;             // etOn groups per emitter: E/N 1, H 2, L 3
    if rank == RANK_HARD { groups = 2; }
    if rank == RANK_LUNATIC { groups = 3; }

    wait(first_wait);

    var vstep: fx = (1fx - v0) / 5fx;   // 6 layers from v0 down to 1.0
    sh_reset(0);
    sh_sprite(0, TH14_OVAL, 4);      // etSprite(1,20,4)
    sh_ring(0, 1);                   // etAim(1,3)
    sh_aim(0, 0);
    sh_count(0, 1, 1);
    sh_xform(0, AT2_TURN_R(tail));
    sh_reset(1);                     // etCopy(2,1) + etExSet2(2,1,...,-pi/2)
    sh_sprite(1, TH14_OVAL, 4);
    sh_ring(1, 1);
    sh_aim(1, 0);
    sh_count(1, 1, 1);
    sh_xform(1, AT2_TURN_L(tail));

    var jit: int = 0;
    var a: int = 0;
    var i: int = 0;
    while self_int(SLOT_TIMEOUT) == 0 {
        // etAngle(1, base + RANDRAD/32, +3deg); etOn(1);  base 22.5/11.25/45 deg
        i = 0;
        while i < groups {
            jit = (rand(65536) - 32768) / 32;
            a = 4096;                 // 0.3926991 rad = 22.5 deg
            if i == 1 { a = 2048; }   // 0.19634955 rad = 11.25 deg
            if i == 2 { a = 8192; }   // 0.7853982 rad = 45 deg
            emit_fan(0, a + jit, 546, v0, vstep);   // 0.05235988 rad = 3 deg
            i = i + 1;
        }
        wait(160);
        if self_int(SLOT_TIMEOUT) != 0 { return; }
        // etAngle(2, base + RANDRAD/32, -3deg); etOn(2);  base 157.5/168.75/135 deg
        i = 0;
        while i < groups {
            jit = (rand(65536) - 32768) / 32;
            a = 28672;                // 2.7488935 rad = 157.5 deg
            if i == 1 { a = 30720; }  // 2.9452431 rad = 168.75 deg
            if i == 2 { a = 24576; }  // 2.3561945 rad = 135 deg
            emit_fan(1, a + jit, -546, v0, vstep);
            i = i + 1;
        }
        wait(gap);
    }
}

// ---- moveRand(60,4,1.0) recipe (ABS, limit x[-140,140] y[0,256]) ----------

sub arm_next_step() {
    var k: int = self_int(SLOT_MOVE_STEP) + 1;
    set_self_int(SLOT_MOVE_STEP, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60fx; }
    var nx: fx = $self_x + self_fx(SLOT_DIR_COS) * speed;
    var ny: fx = $self_y + self_fx(SLOT_DIR_SIN) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_wait(frames: int) {
    var i: int = 0;
    while i < frames {
        if self_int(SLOT_TIMEOUT) != 0 { return; }
        wait(1);
        arm_next_step();
        i = i + 1;
    }
}

sub begin_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -25fx {
        a = r / 3;
    } else if $self_x > 25fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(SLOT_DIR_COS, cos(a as angle));
    set_self_fx(SLOT_DIR_SIN, sin(a as angle));
    set_self_int(SLOT_MOVE_STEP, 0);
    arm_next_step();
}

// ---- boss main: replay common entry, run the attack until native timeout --

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(20fx);                // setHitbox(40,40): circular branch r = 40*0.5
    set_hurtbox(24fx);               // setHurtbox(48,48): circular branch r = 48*0.5

    spawn timeout_watch();
    move_to(100, 0fx, HOME_Y, EASE_QUAD_OUT);   // st01mbs.ecl.txt:39-40, from ENTRY_X/ENTRY_Y
    wait(40);                                   // st01mbs.ecl.txt:41
    wait(160);                                  // MBoss1:61 (EffChargePoint3 visual omitted)

    spawn at2();

    var burst_state: int = 0;        // 0: MBoss1_at(0, +2deg, -10deg); 1: mirrored
    while self_int(SLOT_TIMEOUT) == 0 {
        if burst_state == 0 {
            spawn burst(0deg, LAYER_STEP_2DEG, -10deg);
        } else {
            spawn burst(0deg, -LAYER_STEP_2DEG, 10deg);
        }
        burst_state = 1 - burst_state;
        card_wait(120);
        begin_move_rand();
        card_wait(80);
    }

    // MBossEscape necessary part: drop the field and leave; no follow-up attack.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_to(60, 0fx, -32fx, EASE_QUAD_OUT);
    wait(60);
}

// ---- training shell ------------------------------------------------------

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(ENTRY_X, ENTRY_Y, 8300, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
